doge op, wq[N][M];
unordered_map<doge,int> rt[N];

int read_int() {
    int num=0; char g=getchar();
    while(g<48 || g>57) g=getchar();
    while(g>=48 && g<=57) {
        num=(num<<1)+(num<<3)+g-48;
        g=getchar();
    }
    return num;
