    }
    for(int i=1; i<=e[u-1]; i++) {
        if(!ans[u-1][i]) continue;
        for(int h=1; h<(1<<n); h++) {
            long long opq=1;
            for(int c=0; c<n; c++) {
                if((1<<c)&h) opq=(opq*f[u][c+1])%p;
                else opq=(opq*(1-f[u][c+1]+p)%p);
            }
            doge c=wq[u-1][i], hc=op;
            bool tg=0;
            for(int x=1; x<=q[u-1][0]; x++) {
                if(c[x]==1) {
                    for(int t=0; t<n; t++) {
                        if(((1<<t)&h)&&(!(q[u-1][x]&(1<<t)))) {
                            hc[wf[q[u-1][x]|(1<<t)]]=1; tg=1;
                        }
                    }
                }
            }
            if(!tg) continue;
            int pos;
            if(rt[u][hc]==0) {
                rt[u][hc]=++of; e[u]++; wq[u][e[u]]=hc;
            }
            pos=rt[u][hc];
            ans[u][pos]=(ans[u][pos]+opq*ans[u-1][i])%p;
        }
    }
}

int main() {
    n=read_int();
    for(int i=0; i<=(1<<n); i++) s[i]=__builtin_popcount(i);
    for(int i=1; i<=n; i++)
        for(int j=1; j<=n; j++) f[i][j]=read_int()*mod_pow(100,p-2)%p;
    q[0][0]=1; e[0]=1; ans[0][1]=1; wq[0][1][1]=1;
